//! Integration tests against the public API only.
//!
//! These exercise the crate the way a host does — through `tinyvoice::…`, with
//! no access to private helpers — so a re-export that goes missing fails here
//! even when the unit tests still pass.

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::float_cmp,
    clippy::cast_precision_loss
)]

use tinyvoice::audio::{self, SilenceGateConfig};
use tinyvoice::intent::{VoiceIntent, extract_command, route, wake_word_present};
use tinyvoice::transcript::{Mode, is_hallucinated};
use tinyvoice::vad::{VadConfig, VadEvent, VadSegmenter};
use tinyvoice::{Error, Result};

#[test]
fn the_always_on_pipeline_composes_end_to_end() {
    // The order a host applies these in: gate on the wake word, screen for a
    // hallucination, then try the fast path.
    let heard = "hey tony, pause the music";

    assert!(wake_word_present(heard, "Hey Tiny"));
    let command = extract_command(heard, "Hey Tiny").expect("a command follows the wake word");
    assert_eq!(command, "pause the music");
    assert!(!is_hallucinated(&command, Mode::Conversation));
    assert_eq!(route(&command), VoiceIntent::Pause);
}

#[test]
fn an_unaddressed_utterance_stops_at_the_gate() {
    assert_eq!(extract_command("pause the music", "Hey Tiny"), None);
}

#[test]
fn a_hallucination_is_screened_before_routing() {
    let heard = "hey tiny thank you for watching";
    let command = extract_command(heard, "Hey Tiny").expect("text follows the wake word");
    assert!(
        is_hallucinated(&command, Mode::Conversation),
        "the subtitle phrase must be caught before it reaches the agent"
    );
}

#[test]
fn a_capture_buffer_becomes_a_wav_file() -> Result<()> {
    // Stereo at 32 kHz, as a device might deliver it.
    let stereo: Vec<f32> = (0..2000).map(|i| ((i as f32) / 50.0).sin() * 0.5).collect();

    let mono = audio::to_mono(&stereo, 2)?;
    assert_eq!(mono.len(), 1000);

    let resampled = audio::resample(&mono, 32_000, audio::STT_SAMPLE_RATE)?;
    assert_eq!(resampled.len(), 500);

    let wav = audio::f32_mono_to_wav(&resampled, audio::STT_SAMPLE_RATE)?;
    assert_eq!(&wav[0..4], b"RIFF");
    assert_eq!(&wav[8..12], b"WAVE");
    assert_eq!(wav.len(), 44 + 500 * 2);
    Ok(())
}

#[test]
fn the_silence_gate_is_reachable_and_configurable() -> Result<()> {
    let mut gate = audio::SilenceGate::new(SilenceGateConfig::default(), audio::STT_SAMPLE_RATE)?;
    let loud = vec![0.5f32; 100];
    assert_eq!(gate.push(&loud), loud);
    assert!(!gate.is_gating());
    Ok(())
}

#[test]
fn a_segmenter_carves_an_utterance_out_of_a_stream() {
    let config = VadConfig {
        onset_threshold: 0.1,
        hangover_ms: 100,
        min_speech_ms: 60,
        max_utterance_ms: 5_000,
    };
    let mut seg = VadSegmenter::new(config);

    assert_eq!(seg.push_frame(0.5, 20), Some(VadEvent::SpeechStart));
    for _ in 0..5 {
        assert!(seg.push_frame(0.5, 20).is_none());
    }

    let mut ended = None;
    for _ in 0..10 {
        if let Some(event) = seg.push_frame(0.0, 20) {
            ended = Some(event);
            break;
        }
    }
    match ended {
        Some(VadEvent::SpeechEnd { emit, forced, .. }) => {
            assert!(emit);
            assert!(!forced);
        }
        other => panic!("expected SpeechEnd, got {other:?}"),
    }
}

#[test]
fn errors_are_public_and_matchable() {
    let err = audio::to_mono(&[1.0, 2.0, 3.0], 2).expect_err("ragged");
    assert!(matches!(
        err,
        Error::RaggedFrames {
            samples: 3,
            channels: 2
        }
    ));
}

# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`example-retry-policy.md`](example-retry-policy.md) for a test-first sample.

//! The error type is part of the public surface: hosts match on it, so the
//! variants and their messages are a contract.

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::float_cmp,
    clippy::cast_precision_loss
)]

use super::Error;

#[test]
fn messages_say_what_was_wrong() {
    assert_eq!(
        Error::ZeroSampleRate.to_string(),
        "sample rate must be greater than zero"
    );
    assert_eq!(
        Error::ZeroChannels.to_string(),
        "channel count must be greater than zero"
    );
    assert_eq!(
        Error::RaggedFrames {
            samples: 3,
            channels: 2
        }
        .to_string(),
        "3 samples is not a whole number of 2-channel frames"
    );
}

#[test]
fn errors_are_comparable_so_tests_and_hosts_can_match_on_them() {
    assert_eq!(Error::ZeroSampleRate, Error::ZeroSampleRate);
    assert_ne!(Error::ZeroSampleRate, Error::ZeroChannels);
    assert_ne!(
        Error::RaggedFrames {
            samples: 3,
            channels: 2
        },
        Error::RaggedFrames {
            samples: 5,
            channels: 2
        }
    );
}

//! Ported from `OpenHuman`'s `voice::always_on` VAD tests.
//!
//! Every case drives the segmenter with bare energy numbers — no audio, no
//! device, no clock. That is the point of keeping the state machine pure.

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::float_cmp,
    clippy::cast_precision_loss
)]

use super::{VadConfig, VadEvent, VadSegmenter};

/// Tighter than the shipping default so a test utterance is a few frames
/// rather than a few hundred.
fn cfg() -> VadConfig {
    VadConfig {
        onset_threshold: 0.1,
        hangover_ms: 100,
        min_speech_ms: 60,
        max_utterance_ms: 1000,
    }
}

/// Push `n` frames at a fixed energy and collect whatever comes back.
fn drive(seg: &mut VadSegmenter, rms: f32, frame_ms: u32, n: u32) -> Vec<VadEvent> {
    (0..n)
        .filter_map(|_| seg.push_frame(rms, frame_ms))
        .collect()
}

#[test]
fn silence_emits_nothing() {
    let mut seg = VadSegmenter::new(cfg());
    assert!(drive(&mut seg, 0.0, 20, 50).is_empty());
    assert!(!seg.is_speaking());
}

#[test]
fn onset_then_hangover_emits_one_utterance() {
    let mut seg = VadSegmenter::new(cfg());

    assert_eq!(seg.push_frame(0.2, 20), Some(VadEvent::SpeechStart));
    assert!(seg.is_speaking());
    // 5 more voiced frames -> 120ms voiced total.
    assert!(drive(&mut seg, 0.2, 20, 5).is_empty());

    // Silence accumulates; the hangover is 100ms, so frames 1-4 stay quiet.
    for _ in 0..4 {
        assert!(seg.push_frame(0.0, 20).is_none());
    }
    match seg.push_frame(0.0, 20) {
        Some(VadEvent::SpeechEnd {
            voiced_ms,
            emit,
            forced,
        }) => {
            assert_eq!(voiced_ms, 120);
            assert!(emit, "120ms voiced clears the 60ms minimum");
            assert!(!forced, "closed by hangover, not by the ceiling");
        }
        other => panic!("expected SpeechEnd, got {other:?}"),
    }
    assert!(!seg.is_speaking());
}

#[test]
fn short_blip_is_reported_but_not_emitted() {
    let mut seg = VadSegmenter::new(cfg());
    assert_eq!(seg.push_frame(0.2, 20), Some(VadEvent::SpeechStart));

    let mut end = None;
    for _ in 0..6 {
        if let Some(e) = seg.push_frame(0.0, 20) {
            end = Some(e);
            break;
        }
    }
    match end {
        Some(VadEvent::SpeechEnd {
            voiced_ms, emit, ..
        }) => {
            assert_eq!(voiced_ms, 20);
            assert!(!emit, "20ms is under the 60ms minimum, so drop the audio");
        }
        other => panic!("expected SpeechEnd, got {other:?}"),
    }
}

#[test]
fn mid_utterance_pause_does_not_split() {
    let mut seg = VadSegmenter::new(cfg());
    seg.push_frame(0.2, 20);

    // 80ms of silence: under the 100ms hangover, so the utterance stays open.
    for _ in 0..4 {
        assert!(seg.push_frame(0.0, 20).is_none());
    }
    assert!(
        seg.is_speaking(),
        "a natural pause must not close the segment"
    );

    // Speech resumes and the silence run resets.
    assert!(drive(&mut seg, 0.2, 20, 3).is_empty());
    assert!(seg.is_speaking());
}

#[test]
fn max_utterance_forces_a_flush() {
    let mut seg = VadSegmenter::new(cfg());
    let mut forced_seen = false;

    // Loud throughout: only the ceiling can close this.
    for _ in 0..100 {
        if let Some(VadEvent::SpeechEnd { forced, emit, .. }) = seg.push_frame(0.5, 20) {
            assert!(forced, "a loud-throughout close must be the ceiling");
            assert!(emit);
            forced_seen = true;
            break;
        }
    }
    assert!(forced_seen, "should force-flush at max_utterance_ms");
    assert!(!seg.is_speaking());
}

#[test]
fn hangover_wins_over_the_ceiling_when_both_apply() {
    // A frame can satisfy both conditions. The speaker has actually stopped,
    // so reporting `forced` would tell the host to keep listening for a
    // continuation that is not coming.
    let mut seg = VadSegmenter::new(VadConfig {
        onset_threshold: 0.1,
        hangover_ms: 40,
        min_speech_ms: 10,
        max_utterance_ms: 60,
    });
    seg.push_frame(0.5, 20); // start, total 20
    seg.push_frame(0.0, 20); // total 40, silence 20
    match seg.push_frame(0.0, 20) {
        // total 60 (>= ceiling) and silence 40 (>= hangover)
        Some(VadEvent::SpeechEnd { forced, .. }) => {
            assert!(!forced, "a genuine stop must not be reported as forced");
        }
        other => panic!("expected SpeechEnd, got {other:?}"),
    }
}

#[test]
fn reset_aborts_without_an_event() {
    let mut seg = VadSegmenter::new(cfg());
    seg.push_frame(0.2, 20);
    assert!(seg.is_speaking());

    seg.reset();
    assert!(
        !seg.is_speaking(),
        "the privacy hook drops the partial utterance"
    );

    // And the segmenter is reusable afterwards.
    assert_eq!(seg.push_frame(0.2, 20), Some(VadEvent::SpeechStart));
}

#[test]
fn config_round_trips_as_json_and_rejects_unknown_keys() {
    let cfg = VadConfig::default();
    let json = serde_json::to_string(&cfg).expect("serialize");
    assert_eq!(
        VadConfig::default(),
        serde_json::from_str(&json).expect("deserialize")
    );

    let extra = r#"{"onset_threshold":0.01,"hangover_ms":800,"min_speech_ms":300,"max_utterance_ms":30000,"surprise":1}"#;
    assert!(
        serde_json::from_str::<VadConfig>(extra).is_err(),
        "an unknown key is a caller/host version mismatch, not something to ignore"
    );
}

//! Ported from `OpenHuman`'s `inference::voice::wav` and `voice::audio_capture`
//! tests, plus the boundary cases the originals left to their callers.

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::float_cmp,
    clippy::cast_precision_loss
)]

use super::{
    STT_SAMPLE_RATE, SilenceGate, SilenceGateConfig, f32_mono_to_wav, pcm16_to_wav, resample, rms,
    to_mono,
};
use crate::Error;

// --- WAV framing ---

#[test]
fn writes_a_canonical_44_byte_header() {
    let wav = pcm16_to_wav(&[1, -1, 32767], 16_000, 1).expect("valid");
    assert_eq!(wav.len(), 44 + 6, "header + 3 samples x 2 bytes");
    assert_eq!(&wav[0..4], b"RIFF");
    assert_eq!(&wav[8..12], b"WAVE");
    assert_eq!(&wav[12..16], b"fmt ");
    assert_eq!(&wav[36..40], b"data");
    // RIFF size = 36 + data bytes.
    assert_eq!(
        u32::from_le_bytes(wav[4..8].try_into().expect("4 bytes")),
        42
    );
    assert_eq!(
        u32::from_le_bytes(wav[40..44].try_into().expect("4 bytes")),
        6
    );
    // Sample rate and derived byte rate.
    assert_eq!(
        u32::from_le_bytes(wav[24..28].try_into().expect("4 bytes")),
        16_000
    );
    assert_eq!(
        u32::from_le_bytes(wav[28..32].try_into().expect("4 bytes")),
        32_000
    );
    // Samples are little-endian.
    assert_eq!(&wav[44..46], &1i16.to_le_bytes());
}

#[test]
fn empty_input_still_produces_a_valid_header() {
    let wav = pcm16_to_wav(&[], 16_000, 1).expect("valid");
    assert_eq!(wav.len(), 44);
    assert_eq!(
        u32::from_le_bytes(wav[40..44].try_into().expect("4 bytes")),
        0
    );
}

#[test]
fn a_header_that_no_decoder_could_play_is_refused() {
    assert_eq!(pcm16_to_wav(&[1], 0, 1), Err(Error::ZeroSampleRate));
    assert_eq!(pcm16_to_wav(&[1], 16_000, 0), Err(Error::ZeroChannels));
}

#[test]
fn f32_encoding_clamps_rather_than_wrapping() {
    // 1.5 scaled and cast would wrap to a large negative i16 — an audible
    // crack exactly where the audio was loudest.
    let wav = f32_mono_to_wav(&[1.5, -1.5], STT_SAMPLE_RATE).expect("valid");
    let a = i16::from_le_bytes(wav[44..46].try_into().expect("2 bytes"));
    let b = i16::from_le_bytes(wav[46..48].try_into().expect("2 bytes"));
    assert_eq!(a, 32767);
    assert_eq!(b, -32767);
}

// --- Energy ---

#[test]
fn rms_of_empty_is_zero_not_nan() {
    // A NaN would compare false against every threshold, which reads as
    // "not silent" — the opposite of the truth.
    assert_eq!(rms(&[]), 0.0);
    assert!(!rms(&[]).is_nan());
}

#[test]
fn rms_of_a_constant_signal_is_its_magnitude() {
    assert!((rms(&[0.5, -0.5, 0.5, -0.5]) - 0.5).abs() < f32::EPSILON);
    assert_eq!(rms(&[0.0, 0.0]), 0.0);
}

// --- Downmixing ---

#[test]
fn stereo_averages_to_mono() {
    assert_eq!(
        to_mono(&[1.0, 0.0, 0.5, 0.5], 2).expect("even"),
        vec![0.5, 0.5]
    );
}

#[test]
fn mono_is_returned_unchanged() {
    assert_eq!(
        to_mono(&[0.1, 0.2, 0.3], 1).expect("mono"),
        vec![0.1, 0.2, 0.3]
    );
}

#[test]
fn a_ragged_tail_is_an_error_not_a_silent_truncation() {
    // A ragged tail means the caller and the device disagree about the channel
    // count, so every following sample would land on the wrong channel.
    assert_eq!(
        to_mono(&[1.0, 2.0, 3.0], 2),
        Err(Error::RaggedFrames {
            samples: 3,
            channels: 2
        })
    );
    assert_eq!(to_mono(&[1.0], 0), Err(Error::ZeroChannels));
}

// --- Resampling ---

#[test]
fn matching_rates_are_a_passthrough() {
    let input = [0.1, 0.2, 0.3];
    assert_eq!(
        resample(&input, 16_000, 16_000).expect("same"),
        input.to_vec()
    );
}

#[test]
fn downsampling_halves_the_length() {
    let input: Vec<f32> = (0..100).map(|i| i as f32 / 100.0).collect();
    let out = resample(&input, 32_000, 16_000).expect("valid");
    assert_eq!(out.len(), 50);
}

#[test]
fn upsampling_doubles_the_length_and_interpolates() {
    let out = resample(&[0.0, 1.0], 8_000, 16_000).expect("valid");
    assert_eq!(out.len(), 4);
    assert!((out[0] - 0.0).abs() < 1e-6);
    // Midpoint between the two samples.
    assert!((out[1] - 0.5).abs() < 1e-6);
}

#[test]
fn resampling_never_reads_past_the_end() {
    // The final output index maps onto the last input sample; an off-by-one
    // here is an index panic on every real recording.
    for len in 1..64 {
        let input: Vec<f32> = (0..len).map(|i| i as f32).collect();
        assert!(resample(&input, 44_100, 16_000).is_ok());
        assert!(resample(&input, 16_000, 44_100).is_ok());
    }
}

#[test]
fn empty_and_zero_rates_are_handled() {
    assert_eq!(
        resample(&[], 44_100, 16_000).expect("empty"),
        Vec::<f32>::new()
    );
    assert_eq!(resample(&[0.1], 0, 16_000), Err(Error::ZeroSampleRate));
    assert_eq!(resample(&[0.1], 16_000, 0), Err(Error::ZeroSampleRate));
}

// --- Silence gate ---

fn gate() -> SilenceGate {
    // 1000 samples/sec keeps the arithmetic legible: gate_ms and lookahead_ms
    // map to sample counts one-for-one.
    SilenceGate::new(
        SilenceGateConfig {
            threshold: 0.01,
            gate_ms: 100,
            lookahead_ms: 20,
        },
        1000,
    )
    .expect("valid rate")
}

#[test]
fn speech_passes_through_untouched() {
    let mut g = gate();
    let loud = vec![0.5f32; 50];
    assert_eq!(g.push(&loud), loud);
    assert!(!g.is_gating());
}

#[test]
fn short_silence_is_kept() {
    let mut g = gate();
    let quiet = vec![0.0f32; 50]; // 50 < 100 sample gate
    assert_eq!(g.push(&quiet).len(), 50);
    assert!(!g.is_gating());
}

#[test]
fn sustained_silence_is_dropped() {
    let mut g = gate();
    g.push(&[0.0f32; 50]);
    // Crosses the 100-sample threshold.
    assert!(g.push(&[0.0f32; 60]).is_empty());
    assert!(g.is_gating());
    assert!(g.push(&[0.0f32; 60]).is_empty());
}

#[test]
fn lookahead_is_flushed_so_speech_onset_is_not_clipped() {
    let mut g = gate();
    g.push(&[0.0f32; 200]); // gate closes, look-ahead fills
    assert!(g.is_gating());

    let loud = vec![0.5f32; 10];
    let out = g.push(&loud);
    assert!(!g.is_gating());
    assert!(
        out.len() > loud.len(),
        "the gate returns more than it was given on the reopening block; \
         a caller assuming a length-preserving filter would drop the flush"
    );
    assert_eq!(out.len(), 20 + 10, "retained look-ahead + the new block");
    assert_eq!(&out[20..], &loud[..]);
}

#[test]
fn a_zero_sample_rate_is_refused_at_construction() {
    assert_eq!(
        SilenceGate::new(SilenceGateConfig::default(), 0).err(),
        Some(Error::ZeroSampleRate)
    );
}

//! Ported from `OpenHuman`'s `inference::voice::hallucination` tests, which
//! encode transcripts observed in the field rather than invented ones.

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::float_cmp,
    clippy::cast_precision_loss
)]

use super::{Mode, is_hallucinated};

// --- Exact match, both modes ---

#[test]
fn blank_audio_markers_are_caught() {
    assert!(is_hallucinated("[blank_audio]", Mode::Conversation));
    assert!(is_hallucinated("[ blank_audio ]", Mode::Conversation));
    assert!(is_hallucinated("(blank audio)", Mode::Conversation));
}

#[test]
fn subtitle_phrases_are_caught() {
    assert!(is_hallucinated(
        "Thank you for watching",
        Mode::Conversation
    ));
    assert!(is_hallucinated("please subscribe", Mode::Conversation));
    assert!(is_hallucinated("See you next time.", Mode::Conversation));
}

#[test]
fn punctuation_only_is_caught() {
    assert!(is_hallucinated("...", Mode::Conversation));
    assert!(is_hallucinated(".", Mode::Conversation));
}

// --- The mode split, which is the whole reason `Mode` exists ---

#[test]
fn dictation_drops_single_filler_words() {
    for text in ["you", "okay", "yes", "Thank you."] {
        assert!(
            is_hallucinated(text, Mode::Dictation),
            "{text:?} should be filtered in dictation"
        );
    }
}

#[test]
fn conversation_keeps_the_same_words_as_real_replies() {
    for text in ["yes", "no", "okay", "thank you", "goodbye"] {
        assert!(
            !is_hallucinated(text, Mode::Conversation),
            "{text:?} is a legitimate chat reply and must pass"
        );
    }
}

// --- Repetition layers ---

#[test]
fn uniform_repetition_is_caught_with_and_without_punctuation() {
    assert!(is_hallucinated("you you you you", Mode::Conversation));
    assert!(is_hallucinated("the the the the the", Mode::Conversation));
    assert!(is_hallucinated("it... it... it...", Mode::Conversation));
    assert!(is_hallucinated("it, it, it, it", Mode::Conversation));
}

#[test]
fn repeating_ngram_is_caught_when_no_single_word_dominates() {
    // "thank" and "you" are 50% each — layer 4 cannot see this, layer 3 can.
    assert!(is_hallucinated(
        "Thank you. Thank you. Thank you.",
        Mode::Conversation
    ));
}

#[test]
fn dominant_word_loop_is_caught() {
    // "it" is 8/10 = 80%, count 8.
    assert!(is_hallucinated(
        "it it it it it it it it hello world",
        Mode::Conversation
    ));
}

// --- The false-positive guards. These are the ones that matter: over-eager
// filtering silently deletes real speech, which is worse than letting an
// artefact through. ---

#[test]
fn emphatic_repetition_is_left_alone() {
    // 3/6 = 50%, count 3 — under both bounds.
    assert!(!is_hallucinated(
        "no no no don't do that",
        Mode::Conversation
    ));
    // 3/5 = 60%, which does not *exceed* the ratio, and count 3 < 5.
    assert!(!is_hallucinated("go go go turn left", Mode::Conversation));
}

#[test]
fn moderate_repetition_is_left_alone() {
    // "thank" is 3/7 = 43%.
    assert!(!is_hallucinated(
        "thank you thank you thank you hello",
        Mode::Conversation
    ));
}

#[test]
fn ordinary_sentences_pass() {
    assert!(!is_hallucinated(
        "Can you check the latest price of Bitcoin?",
        Mode::Conversation
    ));
    assert!(!is_hallucinated(
        "I went to the store and the park today",
        Mode::Conversation
    ));
    assert!(!is_hallucinated(
        "Hey team, let's discuss the new feature implementation plan for next sprint",
        Mode::Conversation
    ));
}

#[test]
fn empty_is_not_a_hallucination() {
    // "nothing was said" is a different outcome the host handles separately.
    assert!(!is_hallucinated("", Mode::Conversation));
    assert!(!is_hallucinated("   ", Mode::Conversation));
    assert!(!is_hallucinated("", Mode::Dictation));
}

#[test]
fn two_words_are_below_the_repetition_layers() {
    assert!(!is_hallucinated("hello world", Mode::Conversation));
}

#[test]
fn mode_round_trips_as_json() {
